mapper.insert:
insert ignore into t_rule_hit (
    event_id, device_code, node_id, session_id, user_id,
    mac, rule_id, rule_code, rule_type, action_type, level,
    suppressed, alert_id, hit_time, create_time
) values (
             #{eventId}, #{deviceCode}, #{nodeId}, #{sessionId},
             #{userId}, #{mac}, #{ruleId}, #{ruleCode}, #{ruleType},
             #{actionType}, #{level}, #{suppressed}, #{alertId},
             #{hitTime}, #{createTime}
         )

mapper.select:
select h.rule_code as rule_code, count(*) as hit_count, coalesce(sum(case when h.suppressed = 0 then 1 else 0 end), 0) as actionable_count, coalesce(sum(case when h.suppressed = 1 then 1 else 0 end), 0) as suppressed_count from t_rule_hit h
group by h.rule_code order by hit_count desc, h.rule_code
limit #{criteria.topLimit}
